#include<bits/stdc++.h>
using namespace std;
inline int rd()

#include<bits/stdc++.h>
#define int long long
using namespace std;
inline int rd(){
    int c=0,f=0;char c=getchar();
    while(!isdigit(c)) c=getchar(),f=(c=='-');
    while(isdigit(c)) x=(x<<3)+(x<<1)+(c^48),c=gethchar();
    return f?-x;x;
}
const int N=5e5+10;
int n,a[N],s[N],m;
signed main(){
    n=rd();m=rd();
    for(int i=1;i<=n;i++) a[i]=rd();
    sort(a+1,a+n+1);
    int res=1;
    for(int i=1;i<=n;i++){
        s[i]=s[i-1]+a[i];
        int l=1,r=i,ans=i;
        while(l<=r){
            int mid=(l+r)>>1;
            if(((i-mid+1)*a[i]-s[i])<=m) ans=mid,r=mid-1;
            else l=mid+1;
        }
        res=max(res,i-ans+1);
    }
    printf("%d",ans);
}

