inline int rd(){
    int x=0,f=0;char c=getchar();
    while(!isdigit(c)) f=(c=='-'),c=getchar();
    while(isdigit(c)) x=(x<<3)+(x<<1)+(c^48),c=getchar();
    return f?-x:x;
}
const int N=1e6+10;
vector<pair<int,int> >g[N];
int n,k,a[N],b[N],ban,mx[N],mn,mxf[N],sz[N],lim;
inline void dfs1(int x,int fa){//计算深度
    mx[x]=0;
    for(int i=0;i<g[x].size();i++){
        int v=g[x][i].first;
        if(v==fa||g[x][i].second==ban) continue;
        dfs1(v,x);
        sz[x]+=sz[v];
        mx[x]=max(mx[x],mx[v]+1);
    }
    sz[x]+=(mx[x]>k);
}
inline void dfs2(int x,int fa){
    int cnt=0,_mx=0;
    for(int i=0;i<g[x].size();i++){
        int v=g[x][i].first;
        if(v==fa||g[x][i].second==ban) continue;
        if(mx[v]==mx[x]) cnt++;
        else _mx=max(_mx,mx[v]);
    }
    for(int i=0;i<g[x].size();i++){
        int v=g[x][i].first;
        if(v==fa||g[x][i].second==ban) continue;
        int nv;
        if(mx[x]==mx[v]&&cnt>1) nv=mx[x];
        else nv=_mx;
        mxf[v]=max(mxf[x],nv)+1;
        dfs2(v,x);
    }
    if(mxf[x]<=k) mn=min(mn,sz[x]);
}
bool check(int x){
    lim=x;
    For(i,1,n-1){
        ban=i;
        mn=n;
        dfs1(a[i],0);
        dfs2(a[i],0);
        int nv=mn;
        mn=n;
        dfs1(b[i],0);
        dfs2(b[i],0);
        if((nv+mn)<=k) return 1;
    }
    return 0;
}
void solve(){
    n=rd();k=rd();
    For(i,1,n-1){
        a[i]=rd();b[i]=rd();
        g[a[i]].push_back(make_pair(b[i],i));
        g[b[i]].push_back(make_pair(a[i],i));
    }
    int l=1,r=n,ans=n;
    while(l<=r){
        int mid=(l+r)>>1;
        if(check(mid)) ans=mid,r=mid-1;
        else l=mid+1;
    }
    printf("!!%d\n",ans);
}
signed main(){
    // freopen("migarte.in","r",stdin);
    // freopen("migrate.out","w",stdout);
    int c=rd(),T=rd();
    while(T--) solve();
}

